import unittest

from solution import dispatch_fifo


class DispatchFifoTests(unittest.TestCase):
    def test_fifo_assignment_and_earliest_worker(self):
        self.assertEqual(
            dispatch_fifo([5, 2, 3, 4, 1], 2),
            [(0, 0, 5), (1, 0, 2), (1, 2, 5), (0, 5, 9), (1, 5, 6)],
        )

    def test_ties_choose_lowest_worker_index(self):
        self.assertEqual(
            dispatch_fifo([1, 1, 1, 1, 1, 1], 3),
            [(0, 0, 1), (1, 0, 1), (2, 0, 1), (0, 1, 2), (1, 1, 2), (2, 1, 2)],
        )

    def test_zero_duration_jobs_and_empty_jobs(self):
        self.assertEqual(dispatch_fifo([], 3), [])
        self.assertEqual(
            dispatch_fifo([0, 0, 2, 0], 2),
            [(0, 0, 0), (0, 0, 0), (0, 0, 2), (1, 0, 0)],
        )

    def test_large_integer_duration(self):
        huge = 10 ** 100
        self.assertEqual(dispatch_fifo([huge, 1, 2], 1), [(0, 0, huge), (0, huge, huge + 1), (0, huge + 1, huge + 3)])

    def test_invalid_worker_count(self):
        for value in (True, False, 1.0, "2", None):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    dispatch_fifo([], value)
        for value in (0, -1):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    dispatch_fifo([], value)

    def test_invalid_job_container_and_values(self):
        for jobs in (None, {}, "12", iter([1])):
            with self.subTest(jobs=jobs):
                with self.assertRaises(TypeError):
                    dispatch_fifo(jobs, 1)
        for duration in (True, False, 1.5, "1", None):
            with self.subTest(duration=duration):
                with self.assertRaises(TypeError):
                    dispatch_fifo([duration], 1)
        with self.assertRaises(ValueError):
            dispatch_fifo([-1], 1)

    def test_input_is_not_mutated(self):
        jobs = [3, 1, 2]
        dispatch_fifo(jobs, 2)
        self.assertEqual(jobs, [3, 1, 2])


if __name__ == "__main__":
    unittest.main()

